#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void)
{
    char crop[20] = "maize";
    printf("%s has %zu letters\n", crop, strlen(crop));
    for (int i = 0; crop[i] != '\0'; i++) crop[i] = toupper(crop[i]);
    strcat(crop, " FLOUR");
    printf("%s\n", crop);
    printf("same? %d\n", strcmp(crop, "MAIZE FLOUR") == 0);
    return 0;
}

